const targetName = 'General';

// --- Funciones auxiliares ---

function normalizeName(name) {
  return String(name)
    .toLowerCase()
    .normalize('NFD')                  // separa acentos
    .replace(/[\u0300-\u036f]/g, '')   // elimina acentos
    .trim();
}

function getFilesArray(fromJson) {
  // Caso 1: JSON es un array: [ { files: [...] } ]
  if (Array.isArray(fromJson)) {
    if (!fromJson[0] || !Array.isArray(fromJson[0].files)) {
      throw new Error('No se encontró la propiedad "files" en el primer elemento del array.');
    }
    return fromJson[0].files;
  }

  // Caso 2: JSON es un objeto: { files: [...] }
  if (Array.isArray(fromJson.files)) {
    return fromJson.files;
  }

  throw new Error('No se encontró un arreglo "files" en el JSON recibido.');
}

function findFolderByName(files, name) {
  const normalizedTarget = normalizeName(name);

  return files.find(f => 
    f.mimeType === 'application/vnd.google-apps.folder' &&
    normalizeName(f.name) === normalizedTarget
  ) || null;
}

