// Code node en n8n

// ✅ Nombre base de carpeta a buscar
// Puedes poner "Extras" o traerlo: const targetName = $json.folderName;
const targetName = 'Extra';

// ----------------- Helpers -----------------

function normalizeName(name) {
  return String(name ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')   // quita acentos
    .replace(/\s+/g, ' ')              // colapsa espacios
    .trim();
}

// Variantes típicas: plural/singular, con/ sin espacios, guiones, etc.
function buildVariants(name) {
  const base = normalizeName(name);

  const variants = new Set();
  variants.add(base);

  // si termina en "s", agrega singular; si no termina en "s", agrega plural
  if (base.endsWith('s')) variants.add(base.slice(0, -1));
  else variants.add(base + 's');

  // variantes de formato
  for (const v of Array.from(variants)) {
    variants.add(v.replace(/\s/g, ''));      // sin espacios
    variants.add(v.replace(/\s/g, '-'));     // con guiones
    variants.add(v.replace(/\s/g, '_'));     // con guión bajo
  }

  // si buscas "extra" / "extras", también acepta "extra info", "extras (1)", etc.
  // (esto lo resolvemos con el modo "contains" más abajo)

  return Array.from(variants);
}

function getFilesArray(fromJson) {
  if (Array.isArray(fromJson)) {
    if (!fromJson[0] || !Array.isArray(fromJson[0].files)) {
      throw new Error('No se encontró la propiedad "files" en el primer elemento del array.');
    }
    return fromJson[0].files;
  }
  if (Array.isArray(fromJson.files)) return fromJson.files;

  throw new Error('No se encontró un arreglo "files" en el JSON recibido.');
}

function isFolder(f) {
  return f?.mimeType === 'application/vnd.google-apps.folder';
}

/**
 * Busca carpeta por variantes:
 * 1) match exacto (normalizado)
 * 2) match por "contiene" (normalizado)
 */
function findFolderByVariants(files, baseName) {
  const variants = buildVariants(baseName);

  // Filtra solo folders
  const folders = files.filter(isFolder).map(f => ({
    raw: f,
    norm: normalizeName(f.name),
  }));

  // 1) Exact match
  for (const v of variants) {
    const found = folders.find(x => x.norm === v);
    if (found) return found.raw;
  }

  // 2) Contains match (por si se llama: "Extras Canon", "extra (temario)", etc.)
  for (const v of variants) {
    const found = folders.find(x => x.norm.includes(v));
    if (found) return found.raw;
  }

  return null;
}

// ----------------- Main -----------------

const sourceJson = items[0].json;
const files = getFilesArray(sourceJson);

const folder = findFolderByVariants(files, targetName);

if (!folder) {
  // Para debugging, puedes listar los nombres disponibles:
  const available = files
    .filter(isFolder)
    .map(f => f.name)
    .slice(0, 50);

  throw new Error(
    `No se encontró carpeta para "${targetName}". Variantes probadas: ${buildVariants(targetName).join(', ')}. ` +
    `Folders disponibles (primeros 50): ${available.join(' | ')}`
  );
}

return [{ json: folder }];

for (const item of items) {
  if (!item.binary?.data) throw new Error('No encuentro binary.data');

  item.binary.data.mimeType = 'application/pdf';
  item.binary.data.fileExtension = 'pdf';

  // Si el nombre no termina en .pdf, lo ajustamos
  const name = item.binary.data.fileName || 'documento.pdf';
  item.binary.data.fileName = name.toLowerCase().endsWith('.pdf') ? name : `${name}.pdf`;
}

return items;

